        }
      } finally {
        setLoading(false);
      }
    };

    fetchCourses();

    // Cleanup: abort on unmount or before next effect
    return () => abortControllerRef.current?.abort();
  }, [filters, page]);  // dependencies array

  // ═══ Derived state (no separate useState needed!) ═══
  const hasCourses = courses.length > 0;
  const filteredCount = courses.filter(c => c.price === 0).length;

  return (
    <div>
      {loading && <Spinner />}
      {error && <ErrorBanner message={error} />}
      {hasCourses && <CourseGrid courses={courses} />}
    </div>
  );
}

// ═══ useFetch — reusable data fetching ═══
function useFetch(url, options = {}) {
  const [state, setState] = useState({ data: null, loading: true, error: null });

  useEffect(() => {
    if (!url) return;
    const controller = new AbortController();

    setState(prev => ({ ...prev, loading: true, error: null }));

    fetch(url, { ...options, signal: controller.signal })
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(data => setState({ data, loading: false, error: null }))
      .catch(err => {
        if (err.name !== 'AbortError') {
          setState({ data: null, loading: false, error: err.message });
        }
      });

    return () => controller.abort();
  }, [url]);

  return state;
}

// Usage
function UserProfile({ userId }) {
  const { data: user, loading, error } = useFetch(`/api/users/${userId}`);
  if (loading) return <Spinner />;
  if (error) return <div>Error: {error}</div>;
  return <div>{user.name}</div>;
}

// ═══ useLocalStorage — sync state with localStorage ═══
function useLocalStorage(key, initialValue) {
  const [value, setValue] = useState(() => {
    try {
      const stored = localStorage.getItem(key);
      return stored ? JSON.parse(stored) : initialValue;
    } catch { return initialValue; }
  });

  const setStoredValue = useCallback((newValue) => {
    const toStore = typeof newValue === 'function' ? newValue(value) : newValue;
    setValue(toStore);
    localStorage.setItem(key, JSON.stringify(toStore));
  }, [key, value]);

  return [value, setStoredValue];
}

// ═══ useDebounce — delay expensive operations ═══
function useDebounce(value, delay = 500) {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return debounced;
}

// Usage: only search API when user stops typing for 500ms
function SearchBox() {
  const [query, setQuery] = useState('');
  const debouncedQuery = useDebounce(query, 500);
  const { data: results } = useFetch(debouncedQuery ? `/api/search?q=${debouncedQuery}` : null);
}

// ═══ CONTEXT API — share state without prop drilling ═══
import { createContext, useContext, useReducer } from 'react';

// 1. Create context
const AuthContext = createContext(null);

// 2. Reducer for complex state
function authReducer(state, action) {
  switch (action.type) {
    case 'LOGIN':
      return { ...state, user: action.payload, isAuthenticated: true };
    case 'LOGOUT':
      return { ...state, user: null, isAuthenticated: false };
    case 'UPDATE_PROFILE':
      return { ...state, user: { ...state.user, ...action.payload } };
    default:
      throw new Error(`Unknown action: ${action.type}`);
  }
}

// 3. Provider component
export function AuthProvider({ children }) {
  const [state, dispatch] = useReducer(authReducer, {
    user: null,
    isAuthenticated: false,
  });

  const login = async (credentials) => {
    const user = await authService.login(credentials);
    dispatch({ type: 'LOGIN', payload: user });
  };

  const logout = async () => {
    await authService.logout();
    dispatch({ type: 'LOGOUT' });
  };

  return (
    <AuthContext.Provider value={{ ...state, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

// 4. Custom hook for consuming context
export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

// 5. Usage — any deeply nested component
function UserMenu() {
  const { user, isAuthenticated, logout } = useAuth();
  if (!isAuthenticated) return <LoginButton />;
  return (
    <div>
      <span>Welcome, {user.name}!</span>
      <button onClick={logout}>Logout</button>
    </div>
  );
}

