import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';

// ═══ PASSWORD HASHING (never store plaintext!) ═══
const SALT_ROUNDS = 12;  // bcrypt cost factor — 2^12 iterations

async function hashPassword(plaintext) {
  return bcrypt.hash(plaintext, SALT_ROUNDS);
}

async function verifyPassword(plaintext, hash) {
  return bcrypt.compare(plaintext, hash);
}

// ═══ TOKEN GENERATION ═══
function generateTokenPair(userId, role) {
  const payload = { sub: userId, role };

  const accessToken = jwt.sign(payload, process.env.JWT_SECRET, {
    expiresIn: '15m',   // short-lived — minimize attack global
    issuer: 'learnxchain.com',
    audience: 'learnxchain.com/api'
  });

  const refreshToken = jwt.sign(
    { sub: userId, type: 'refresh' },
    process.env.JWT_REFRESH_SECRET,
    { expiresIn: '7d' }
  );

  return { accessToken, refreshToken };
}

// ═══ LOGIN ENDPOINT ═══
async function loginHandler(req, res) {
  const { email, password } = req.body;

  // Always query user — even if not found, run bcrypt compare
  // to prevent timing attacks (user enumeration)
  const user = await db.users.findUnique({ where: { email } });
  const DUMMY_HASH = '$2b$12$invalidhashtopreventtimingattacks';
  const isValid = await verifyPassword(password, user?.passwordHash ?? DUMMY_HASH);

  if (!user || !isValid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const { accessToken, refreshToken } = generateTokenPair(user.id, user.role);

  // Store refresh token (hash it first!) in DB for rotation/revocation
  await db.refreshTokens.create({
    data: { userId: user.id, tokenHash: await bcrypt.hash(refreshToken, 10) }
  });

  // Set refresh token in HttpOnly cookie (XSS-safe)
  res.cookie('refreshToken', refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000  // 7 days in ms
  });

  // Send access token in response body (stored in memory by client)
  res.json({ accessToken, user: { id: user.id, name: user.name, role: user.role } });
}

