import Redis from 'ioredis';

const redis = new Redis(process.env.REDIS_URL);

// ═══ CACHE-ASIDE PATTERN (most common) ═══
async function getCourse(courseId) {
  const cacheKey = `course:${courseId}`;

  // 1. Check cache first (L1)
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);  // Cache HIT — fast!

  // 2. Cache miss — fetch from database
  const course = await prisma.courses.findUnique({
    where: { id: courseId },
    include: { instructor: true, lessons: true }
  });

  if (!course) return null;

  // 3. Store in cache with TTL (time-to-live)
  await redis.setex(cacheKey, 3600, JSON.stringify(course));  // 1 hour TTL

  return course;  // Cache MISS — slow, but next read is fast
}

// ═══ CACHE INVALIDATION — the hard problem ═══
async function updateCourse(courseId, data) {
  const course = await prisma.courses.update({
    where: { id: courseId },
    data
  });

  // Invalidate cache so stale data isn't served
  await redis.del(`course:${courseId}`);

  // Also invalidate any list caches that include this course
  await redis.del('courses:list:*');  // pattern delete

  return course;
}

// ═══ SESSION CACHING ═══
async function getSession(sessionId) {
  const session = await redis.get(`session:${sessionId}`);
  return session ? JSON.parse(session) : null;
}

async function createSession(userId, data) {
  const sessionId = crypto.randomUUID();
  await redis.setex(`session:${sessionId}`, 86400, JSON.stringify({ userId, ...data }));
  return sessionId;
}

// ═══ RATE LIMITING with Redis ═══
async function checkRateLimit(ip, limit = 100, windowSeconds = 900) {
  const key = `rate:${ip}`;
  const requests = await redis.incr(key);
  if (requests === 1) await redis.expire(key, windowSeconds);  // Set TTL on first request
  return requests <= limit;  // true = allowed, false = blocked
}

